  AwakerTalent_117311_TalentDesc_1 = {
    Text = [[
The first Command Card Pollux plays in a turn deals DMG+200% of his ATK, generates Shield +50% of his DEF, and +10 Aliemus.
After the battle, Pollux's Base DMG and the "Atonement by Pain" DMG effect +20% in exploration, and the "Atonement by Pain" DMG effect is doubled in Boss Battle.]]
  },
  AwakerTalent_117311_TalentName_1 = {
    Text = "Atonement by Pain"
  },
  AwakerTalent_120347_TalentDesc_1 = {
    Text = "When this character is in the team, the Aequor Realm transforms into \"Benthos: Aequor\" Realm.\nBase Tentacle DMG is changed to 5% of the team's Max HP.\nTeam DMG Amplification +50% after exploration begins (Effect doubled if the team is entirely Aequor and Chaos Awakeners, though no additional starting Tentacles will be obtained).\nTentacle Gathering effect is removed.\nTentacle Stance changes to \"Benthos: Tentacle Stance\".\n\"Benthos: Tranquil Sea\": Immediately generate Shield equal to 25% Max HP, and Tentacles will no longer attack at turn end; 3 turns cooldown.\n\"Benthos: Raging Waves\": Tentacle DMG × 125% for the turn; after dealing Active DMG, 1 Tentacle attacks; lose 1 Tentacle at turn end; 3 turns cooldown.\nRealm Mastery is counted as \"Benthos: Aequor Mastery.\" Each point provides: Tranquil Sea Stance's Shield Generation +0.025% Max HP. Raging Waves Stance's Tentacle DMG +0.025%.\n\"Benthos: Realm Mastery\" effect doubles if the team is entirely Aequor and Chaos Awakeners."
  },
  AwakerTalent_120347_TalentName_1 = {
    Text = "Lightless Bottom"
  },
  AwakerTalent_122481_TalentDesc_1 = {
