  AwakerTalent_125362_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF +[Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
All Awakeners' Poison Trigger effect +[Arg3]%.
Each stack of "Spellbound" additionally reduces the DMG dealt by "Humanoid" enemies by 1%, and when "Spellbound" is removed, each stack deals Pure DMG equal to 1% of target's Max HP on "Humanoid" enemies.]]
  },
