  AwakerTalent_127223_TalentDesc_1 = {
    Text = "When Arachne is in the team, the Ultra Realm reweaves into Singularity: Ultra.\nDimension Shuttle: After playing the first Command Card each turn, a Fleeting, Basic Copy of it will be put into Ultra Space and granted 25 stacks of Singularity Beacon. This cannot trigger during Ultra Rounds. If a card triggers Dimension Shuttle, it also benefits from the effects of Singularity Beacon.\nSingularity Beacon: For each stack, a card's Final DMG, Fixed STR & Tentacle DMG gain, Fixed Poison & Counter each +2%; Final Shield, HP Recovery, and STR▼ each +1%. This effect clears when the card is played. Cards with this effect cannot trigger Dimension Shuttle.\nUltra Space: When full, beginning the Ultra Round does not end the turn nor does it start one; discard all non-Retain cards, resolve their Fleeting effects, pull all cards from Ultra Space, and set Arithmetica to 5. This current turn continues as an Ultra Round.\nSingularity Annihilation: Pull the leftmost card out from Ultra Space and into hand. 3 turns cooldown.\nAt the start of investigation, gain +50% DMG Amplification and 15 stacks of Singularity Prism.\nSingularity Prism: All Command Cards' effects increase as though they had this many stacks of Singularity Beacon.\nUltra Mastery: For each 1 point of Realm Mastery, Singularity Beacon stacks from Singularity Prism and Dimension Shuttle increase by 0.05%.\nPure Ultra: If the team consists only of Ultra or Chaos Awakeners, the Ultra Mastery effect and Realm DMG Amplification are doubled."
  },
