  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·This Talent only takes effect in \"Stellar Chapter\" stages.\n·This Awakener's CON, ATK, and Defense are increased by [Arg1]%, and after this Awakener plays Rouse for the first time, gain [Arg2] Keyflare.\n·\"Boundless Wasteland Shadow\" STR▼ Effect and STR multiplier gained are increased by [Arg3]%. Each time it takes effect, the next \"Sin-Stained Gunpoint\" gains an additional [Arg4]% STR bonus, up to a maximum of 1200%."
