  AwakerTalent_145718_TalentDesc_1 = {
    Text = "When Caraboo is on the team, the Caro Realm is tricked into becoming Propagation: Caro.\n\nEmbryo Fusion: The Embryo Fusion gained per turn increases to 50~100, scaling with HP lost. The Embryo Fusion cap increases from 100 to 200. Upon reaching the cap, add 1 \"Propagule Embryo\" into hand.\n\nPropagule Embryo: Playing this card no longer grants Crit. Rate. Devour no longer grants Shield or Temporary STR. The first time each Awakener consumes a \"Propagule Embryo\" each turn, they gain 40 stacks of \"Propagation Fiesta\": Each stack enhances the following Final effects of that Awakener's next Exalt this turn by 1%: Final DMG, Fixed Shield, Fixed HP Recovery, Fixed STR/STR▼, Tentacle DMG Bonus, Fixed Poison, and Fixed Counter.\n\nCrimson Furnace: The auto-accumulation At turn start changes to 10% of HP lost, up to 50% of Max HP. No longer accumulates at the end of battle. 3 turns cooldown.\n\nCrimson Corrosion: After using Crimson Furnace, inflict Corrosion on all enemies equal to 1% of their Max HP. The more Crimson Furnace consumed, the stronger the Corrosion effect, up to +100%. Deals 5× Corrosion effect against \"Empty Shell\" enemies.\n\nAt the start of exploration, Max HP +10%, team DMG Amplification +50%, and all Awakeners gain 20 stacks of \"Propagation Fiesta\" At turn start. If the team consists only of Caro or Chaos Awakeners, the DMG Amplification granted by this effect is doubled.\nRealm Mastery becomes \"Propagation: Caro Mastery\": Each point of Realm Mastery increases the \"Propagation Fiesta\" stacks gained from \"Propagation: Caro\" by 0.05%.\n\nIf the team consists only of Caro or Chaos Awakeners, the \"Propagation: Caro Mastery\" effect is doubled."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Eden of Propagation"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "When Lotan: Cetarchon is on the team, the Chaos Realm reforges into Primordia: Chaos.\n\nPrimordial Influx: Base Keyflare is increased to 2000, Team DMG Amplification is increased by 50%, and all Awakeners' ATK and DEF are increased by 10%. If the team consists solely of Chaos Awakeners, the DMG Amplification bonus from this effect is doubled. At the start of battle, gain 2000 Keyflare.\n\nConfluent Keys: All Awakeners' Keyflare Regen Levels are set to the team average. Awakeners no longer gain Keyflare from Arithmetica consumed; instead, the first Command Card played by each Awakener per turn grants Keyflare equal to (their Keyflare Regen × 3) + 100.\n\nIndivisible Realm: No longer triggers other Realms' Pure Realm, Double Realm Mastery, or Double DMG Amplification effects.\n\nPrimordial Echo: Rouse Cards gain Prepare 1; the currently equipped Posse is automatically unleashed the first time they are played each turn.\n\nMemory Fragments: Posse is replaced with Primordia: Dual Recurrence and Primordia: Triad Revelation, and the carried Posse itself can no longer be unleashed.\n\n-Primordia: Dual Recurrence: Discover 3 Posses from those in hand, then choose 1 to unleash twice.\n-Primordia: Triad Revelation: Discover 3 sets of Posses from those in hand, each set containing 3 different Posses. Choose one set to unleash each Posse within it once, in sequence.\nThe Posses featured in Primordia: Dual Recurrence and Primordia: Triad Revelation are drawn from the eight types of Primordial Memory.\nPrimordia: Dual Recurrence and Primordia: Triad Revelation each count as unleashing only 1 Posse. When their effects would trigger multiple times, only the first Posse to take effect is valid.\n\nPrimordia: Chaos Mastery: Realm Mastery becomes Primordia: Chaos Mastery. Each point of Primordia: Chaos Mastery increases the Posse Potency by 0.05%. Each point of Posse Potency increases Fixed Poison, Fixed Counter, Fixed STR, Fixed Ancient Embers by 2%, and Fixed Shield, Fixed HP Recovery, Fixed STR ▼ & Tentacle DMG gain, Crit. Rate, Crit. DMG, DMG Amplification, Realm Mastery, Aliemus Generation, Embryo Fusion, and Keyflare Generation by 1%."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Primordial Breath"
  },
