  AwakerTalent_78645_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF +[Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
The STR gained by all Awakeners +[Arg3]%.
When Clementine deals DMG to "Insectoid" enemies, she inflicts a Bleed effect equal to [Arg4]% of the DMG dealt. The first time each turn Clementine provides a Shield or recovers HP, "Insectoid" enemies temporarily lose STR equal to [Arg5]% of Clementine's DEF.]]
