  AwakerTalent_84132_TalentDesc_1 = {
    Text = "For every 1 Aliemus Regen Level Aurita has, gain Tentacle DMG equal to 1% of her ATK at the start of battle. For every 1% Crit. Rate Aurita has, gain Tentacle DMG equal to 1% of her ATK at the start of battle."
